#include <cstdio>

const long long MOD = 1000000007LL;

long long normalize(long long value) {
    value %= MOD;
    if (value < 0) value += MOD;
    return value;
}

int main() {
    long long x, y, n;

    while (scanf("%lld %lld %lld", &x, &y, &n) == 3) {
        long long ans[6] = {
            normalize(x),
            normalize(y),
            normalize(y - x),
            normalize(-x),
            normalize(-y),
            normalize(x - y)
        };

        printf("%lld\n", ans[(n - 1) % 6]);
    }

    return 0;
}

